'use strict';
// UX01: fixed, explicitly labelled example states. No production interpreter,
// persistence, network calls, pupil data, or automatic assessment of explanations.
const main=document.querySelector('#main');
const draftInputs={};
let runPrediction=null;
const revisionEvidence={before:null,after:null};
const state={screen:'einstieg',mode:null,s0:0,s1:0,corrected:false,run:false,step:0,compare:false,savedBefore:false,savedAfter:false,answer:'',rationale:'',returnPoint:'Warum dreht der Wagen bei Aktion 5 nach links?',next:'Aktion 5 in meiner Grafik und im Code vergleichen.',retrieval:false,retrieved:false,s3view:'plan',s3run:false,s3saved:false,s3step:5};
const names=['oben','rechts','unten','links'];
const arrows=['↑','→','↓','←'];
const s0=[[1,3,0],[1,2,0],[1,2,1],[2,2,1]];
const s1=[[2,3,1],[3,3,1],[3,3,0],[3,2,0],[3,2,3],[2,2,3],[2,2,2],[2,3,2],[2,3,1]];
const bad=[[2,3,1],[3,3,1],[4,3,1],[4,3,1]];
const s3=[[1,3,1],[2,3,1],[3,3,1],[3,3,0],[3,2,0],[3,2,3],[2,2,3],[1,2,3],[1,2,2],[1,3,2],[1,3,1]];
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function svgGrid(w,h,pos,trail=[],points=[]){const cell=60,left=30,top=26;let content='';for(let x=1;x<=w;x++)content+=`<text x="${left+(x-.5)*cell}" y="17" text-anchor="middle" font-size="13" fill="#52646b">${x}</text>`;for(let y=1;y<=h;y++){content+=`<text x="14" y="${top+(y-.5)*cell+5}" text-anchor="middle" font-size="13" fill="#52646b">${y}</text>`;for(let x=1;x<=w;x++){const p=points.findIndex(v=>v[0]===x&&v[1]===y);content+=`<rect x="${left+(x-1)*cell}" y="${top+(y-1)*cell}" width="${cell}" height="${cell}" fill="${p>=0?'#edf6f1':'#fff'}" stroke="#a4b9bb"/><text x="${left+(x-1)*cell+5}" y="${top+(y-1)*cell+14}" font-size="10" fill="#52646b">${x},${y}${p>=0?' · '+(p+1):''}</text>`;}}
if(trail.length>1)content+=`<polyline points="${trail.map(p=>`${left+(p[0]-.5)*cell},${top+(p[1]-.5)*cell}`).join(' ')}" stroke="#377d70" stroke-width="4" fill="none" stroke-dasharray="6 4"/>`;
content+=`<circle cx="${left+(pos[0]-.5)*cell}" cy="${top+(pos[1]-.5)*cell}" r="19" fill="#176657"/><text x="${left+(pos[0]-.5)*cell}" y="${top+(pos[1]-.5)*cell+8}" fill="white" text-anchor="middle" font-size="28">${arrows[pos[2]]}</text>`;
return `<div class="grid-wrap"><svg class="grid-svg" viewBox="0 0 ${left+w*cell+4} ${top+h*cell+4}" role="img" aria-label="${w} mal ${h} Raster. Wagen bei (${pos[0]},${pos[1]}), Blick ${names[pos[2]]}. Spalten von links, Zeilen von oben.">${content}</svg><div class="legend"><span>Spalte → · Zeile ↓</span><span>Wagen: (${pos[0]},${pos[1]}) · ${names[pos[2]]}</span></div></div>`;}
function prediction(prefix='p'){return `<div class="prediction"><div><label for="${prefix}-x">Spalte am Ende</label><input id="${prefix}-x" type="number" min="1" max="5" inputmode="numeric"></div><div><label for="${prefix}-y">Zeile am Ende</label><input id="${prefix}-y" type="number" min="1" max="4" inputmode="numeric"></div><div><label for="${prefix}-d">Blick am Ende</label><select id="${prefix}-d"><option value="">Noch unsicher</option>${names.map(n=>`<option>${n}</option>`).join('')}</select></div></div>`;}
function help(){return `<details class="help"><summary>Ich komme nicht weiter</summary><p><strong>Ort oder Blick?</strong> Bei einer Drehung bleibt der Wagen im Feld. Drehe nur seinen Blickpfeil. Sage dann den nächsten Zustand voraus.</p><p><strong>Was wird wiederholt?</strong> Zeige auf den ganzen Rahmen. Lies die Anweisungen darin einmal in Reihenfolge. Was kommt beim zweiten Durchlauf?</p><p><strong>Wo beginnt der Fehler?</strong> Vergleiche ab Aktion 1. Die erste Abweichung kann vor der Fehlermeldung liegen.</p><p>Du kannst deine Erklärung auch zeigen und mündlich begründen. Wenn ein Begriff oder die Bedienung unklar bleibt, frage die Lehrkraft.</p></details>`;}
function entry(){return `<div class="eyebrow">Ort &amp; Blick · Einstieg</div><h1>Wohin fährt der Wagen?</h1><p class="lead">Ein Wagen kann deine Absicht nicht erraten. Du gibst ihm genaue Anweisungen – und prüfst, ob er wirklich so fährt, wie du denkst.</p><div class="split start-split"><section class="card"><h2>Deine erste Prüffahrt</h2><p>Start: <strong>(1,3), Blick nach oben.</strong><br>Lies die drei Befehle. Wo steht der Wagen danach, und wohin blickt er?</p><div class="command-strip"><span>1 · vor</span><span>2 · rechts drehen</span><span>3 · vor</span></div><p class="micro">„vor“: ein Feld in Blickrichtung. „rechts“: im selben Feld um eine Vierteldrehung nach rechts drehen.</p>${!state.mode?`<div class="feedback"><strong>So beginnst du</strong><p>Wähle zuerst deinen Speicherweg. Danach gibst du deine Vorhersage ein.</p></div><div class="choice"><button class="primary" data-action="device">Auf diesem Gerät beginnen</button><p>Im späteren Produkt bleibt deine Arbeit in diesem Browserprofil. Nutze das nur nach Absprache auf Schulgeräten.</p><button data-action="session">Nur für diese Sitzung beginnen</button><p>Im späteren Produkt brauchst du vor dem Schließen eine Datei, wenn du deine Arbeit behalten möchtest.</p><p class="micro">Hier werden beide Möglichkeiten nur gezeigt; es wird nichts dauerhaft gespeichert.</p></div>`:`<label for="s0-answer">Meine Vorhersage · zeige oder beschreibe Ort und Blick</label><textarea id="s0-answer" placeholder="Ich vermute …, weil …">${esc(state.answer)}</textarea><div class="actions"><button class="primary" data-action="s0-next" ${state.s0===3?'disabled':''}>Einen Schritt prüfen</button><button data-action="s0-reset">Zum Startzustand</button></div><p class="micro">Du darfst auch mit einer offenen Vermutung prüfen.</p>${state.s0?`<div class="feedback" role="status"><strong>Aktion ${state.s0} · ${['','vor','rechts drehen','vor'][state.s0]}</strong><p>${state.s0===2?'Der Ort bleibt (1,2). Nur die Blickrichtung ändert sich nach rechts.':`Der Wagen steht jetzt (${s0[state.s0][0]},${s0[state.s0][1]}), Blick ${names[s0[state.s0][2]]}.`}</p><p>Vergleiche das mit deiner Vorhersage.</p></div>`:''}${state.s0===3?'<button data-screen="beispiel">Weiter: Wiederholung verstehen →</button>':''}`}</section><section class="card soft"><h2>Der Wagen im Raster</h2>${svgGrid(3,3,s0[state.s0],s0.slice(0,state.s0+1))}<p class="micro" style="margin-top:18px">Die erste Zahl nennt die Spalte, die zweite die Zeile. Der Pfeil zeigt die Blickrichtung.</p></section></div>${help()}`;}
function example(){return `<div class="eyebrow">Wiederholung verstehen · S1</div><h1>Welche Befehle gehören zusammen?</h1><p class="lead">Ein Durchlauf besteht aus <strong>vor und links drehen</strong>. Der ganze Körper wird viermal ausgeführt.</p><div class="split"><section class="card"><h2>Beispiel gemeinsam prüfen</h2><div class="code"><strong>wiederhole 4</strong><div class="body-frame"><div class="caption">Ein vollständiger Körper</div><div class="code-row">1 · vor</div><div class="code-row">2 · links drehen</div></div><span class="micro">Körperende → nächster Durchlauf</span></div><div class="feedback"><strong>${state.s1===4?'Stopp: zwei Durchläufe':'Erst denken, dann prüfen'}</strong><p>${state.s1===4?'Wo steht der Wagen? Zeige den ganzen Körper. Welcher Befehl kommt als Nächstes?':'Sage Ort und Blick nach „vor“ und nach „links“ voraus. Warum verändert die Drehung den Ort nicht?'}</p></div><label for="example-answer">Meine Erklärung oder Unsicherheit</label><textarea id="example-answer" placeholder="Zeige oder erkläre einen Zustandswechsel."></textarea><div class="actions"><button class="primary" data-action="s1-next" ${state.s1===8?'disabled':''}>Einen Schritt prüfen</button><button data-action="s1-reset">Zum Start</button></div></section><section class="card soft"><h2>Aktion ${state.s1} von 8</h2>${svgGrid(4,4,s1[state.s1],s1.slice(0,state.s1+1))}<p class="micro" style="margin-top:12px">Start: (2,3), Blick rechts. Bei Aktion 2 und 4 hältst du inne und erklärst.</p></section></div><section class="card"><h2>Jetzt ergänzt du selbst</h2><p>Die angefangene Grafik enthält <strong>wiederhole 4 [vor; …]</strong>. Ergänze den fehlenden Befehl und begründe den nächsten Zustandswechsel. Diese Aufgabe bleibt dein eigenes Produkt P1.</p><label for="p1-command">Mein ergänzter Befehl</label><select id="p1-command"><option>Ich entscheide …</option>vor</option>links</option>rechts</option></select><p class="micro">Dieses Eingabefeld zeigt die eigenständige Ergänzung; es bewertet sie nicht.</p><div class="actions"><button data-screen="revision">Weiter: Einen Fehler untersuchen →</button></div></section>${help()}`;}
function revision(){const trace=state.corrected?s1:bad;const last=trace.length-1;const pos=trace[Math.min(state.step,last)];return `<div class="eyebrow">Einen Fehler untersuchen · S2 · eigener Vergleich</div><h1>Wo beginnt die falsche Fahrt?</h1><p class="lead">Die Fahrt soll wie im Beispiel verlaufen. Prüfe die Körpergrenze: Wird wirklich in jedem Durchlauf gefahren <em>und</em> gedreht?</p><div class="split"><section class="card"><div class="row" style="justify-content:space-between"><h2>Mein Code · ${state.corrected?'Revision':'Ausgangsfassung'}</h2><span class="tag">S2 · 4 × 4</span></div><div class="code"><strong>wiederhole 4</strong><div class="body-frame"><div class="caption">Diese Anweisungen gehören zum Körper</div><div class="code-row ${state.run?'current':''}"><span><span class="n">1</span>vor</span></div>${state.corrected?'<div class="code-row"><span><span class="n">2</span>links drehen</span><button data-action="ungroup">Aus dem Körper</button></div>':''}</div>${!state.corrected?'<div class="code-row"><span><span class="n">danach</span>links drehen</span><button data-action="group">In den Körper verschieben</button></div>':''}<p class="micro">Eine Verschiebung verändert deinen Code. Der ausgewählte Vorherbeleg bleibt erhalten.</p></div>${!state.run?`<h3 style="margin-top:18px">Meine Vorhersage</h3>${prediction('s2')}<div class="actions"><button class="primary" data-action="run-s2">Code prüfen</button></div><p class="micro">Ausführen geht auch ohne Vorhersage. Ein Beleg braucht eine eigene Erwartung vor diesem Lauf.</p>`:`<div class="feedback ${state.corrected?'':'warn'}" role="status"><strong>${state.corrected?'Ausführung beendet. Prüfe deine Änderung.':'Stopp an der Rastergrenze.'}</strong><p>${state.corrected?'Acht Aktionen führen zurück nach (2,3), Blick rechts. Das erklärt noch nicht, warum deine Körpergrenze passt.':'Aktion 3 würde aus dem Raster fahren. Der Wagen bleibt bei (4,3), Blick rechts. Der erste Unterschied zur geplanten Fahrt kann früher liegen.'}</p><button data-action="compare" class="quiet">Soll und Ist vergleichen</button></div>`}</section><section class="card soft"><h2>Wagen &amp; Spur</h2><p class="micro">S2 · Start (2,3), Blick rechts · ${state.run?'Ausführung zum angezeigten Code':'noch kein Lauf'}</p>${svgGrid(4,4,pos,trace.slice(0,state.step+1))}<div class="step-controls"><button data-action="prev" aria-label="Vorige Aktion" ${!state.run||state.step===0?'disabled':''}>←</button><strong>Aktion ${state.step} / ${state.run?last:'–'}</strong><button data-action="next" aria-label="Nächste Aktion" ${!state.run||state.step===last?'disabled':''}>→</button></div><p class="micro" style="margin-top:10px">${state.step?`Nach Aktion ${state.step}: (${pos[0]},${pos[1]}), Blick ${names[pos[2]]}. ${!state.corrected&&state.step===3?'Der versuchte Schritt verändert den Zustand nicht.':''}`:'Noch keine Anweisung ausgeführt.'}</p></section></div>${state.compare?`<section class="card"><h2>Finde die erste Abweichung</h2><p>Vergleiche Zustand und Befehl ab Aktion 1. Markiere zuerst deine Vermutung.</p><table class="trace"><caption>Soll: S1 · Ist: dein ${state.corrected?'revidierter':'ursprünglicher'} S2-Code</caption><thead><tr><th>Aktion</th><th>Soll</th><th>Ist</th></tr></thead><tbody>${[1,2,3].map(i=>`<tr><th>${i}</th><td>(${s1[i][0]},${s1[i][1]}), ${names[s1[i][2]]}</td><td>(${trace[i][0]},${trace[i][1]}), ${names[trace[i][2]]}</td></tr>`).join('')}</tbody></table><label for="first-diff">Meine erste Abweichung</label><select id="first-diff"><option value="">Ich vergleiche noch …</option><option>1</option><option>2</option><option>3</option><option>Keine in diesen drei Aktionen</option></select><label for="why">Meine Begründung zur ${state.corrected?'Revision':'Ausgangsfassung'}</label><textarea id="why" placeholder="In Aktion … geschieht …; geplant war …">${esc(state.rationale)}</textarea><div class="actions"><button data-action="record" class="primary">${state.corrected?'Nachherbeleg':'Vorherbeleg'} übernehmen</button></div><p class="receipt" id="receipt" role="status">${state.savedBefore?'Vorherbeleg im Beispielvergleich vorhanden.':''} ${state.savedAfter?'Nachherbeleg im Beispielvergleich vorhanden.':''}</p><p class="micro">Die Begründung bleibt deine eigene. „Übernommen“ bedeutet noch nicht dauerhaft gespeichert oder fachlich bestätigt. Hier wird die Belegauswahl nur simuliert.</p></section>`:''}${help()}<div class="savebar"><p>${state.savedBefore?'Vorherbeleg: vorhanden · ':'Vorherbeleg: offen · '}${state.savedAfter?'Nachherbeleg: vorhanden':'Nachherbeleg: offen'}</p><button data-screen="rueckkehr">Stand für die Rückkehr festhalten</button><button data-screen="entwurf">Zur eigenen Prüffahrt →</button></div>`;}
function design(){const i=state.s3step;return `<div class="eyebrow">Meine Prüffahrt · S3</div><h1>Dein Plan. Dein Code. Deine Prüfung.</h1><p class="lead">Besuche (3,3), (3,2), (1,2) und (1,3) in dieser Reihenfolge. Fahre am Rechteckrand und ende mit Blick nach rechts. Nutze eine feste Wiederholung.</p><div class="feedback warn"><strong>Vorbereiteter Beispielstand für diesen UX-Review</strong><p>Diese Ansicht zeigt einen möglichen Entwurf. Im Produkt beginnt S3 leer; Grafik und Code werden von Lernenden getrennt erstellt. Hier ist kein freier Editor implementiert.</p></div><div class="split"><section class="card"><div class="tabs"><button data-action="plan" aria-pressed="${state.s3view==='plan'}">Meine Ablaufgrafik</button><button data-action="code" aria-pressed="${state.s3view==='code'}">Mein Code</button></div><h2>${state.s3view==='plan'?'Mein eigener Plan':'Meine ausführbare Fassung'}</h2><p class="micro">Getrennte Produkte · keine automatische Kopie</p><div class="code"><p>${state.s3view==='plan'?'Start → Körper mit Anzahl 2 → Ende':'wiederhole 2'}</p><div class="body-frame"><div class="caption">Ein vollständiger Körper · zweimal</div>${['vor','vor','links drehen','vor','links drehen'].map((c,j)=>`<div class="code-row ${state.s3run&&j===(i-1)%5?'current':''}"><span>${j+1} · ${c}</span></div>`).join('')}</div></div><p class="quote">„Nach einer langen und einer kurzen Seite blickt der Wagen in die Gegenrichtung.“</p><p class="micro">Beispielerklärung. Zeige in Grafik und Code, welche Anweisung die Blickrichtung verändert.</p><div class="actions"><button class="primary" data-action="s3-run">Vorbereiteten Prüflauf ansehen</button></div></section><section class="card soft"><h2>Prüfpunkte 1 bis 4</h2>${svgGrid(5,4,state.s3run?s3[i]:s3[0],state.s3run?s3.slice(0,i+1):[],[[3,3],[3,2],[1,2],[1,3]])}${state.s3run?`<div class="step-controls"><button data-action="s3-prev" aria-label="Vorige S3-Aktion" ${i===1?'disabled':''}>←</button><strong>Aktion ${i} von 10</strong><button data-action="s3-next" aria-label="Nächste S3-Aktion" ${i===10?'disabled':''}>→</button></div><p class="micro">Durchlauf ${Math.ceil(i/5)} · Befehl ${(i-1)%5+1} · (${s3[i-1][0]},${s3[i-1][1]}), ${names[s3[i-1][2]]} → (${s3[i][0]},${s3[i][1]}), ${names[s3[i][2]]}</p>`:''}</section></div>${state.s3run?`<section class="card"><h2>Was ist geprüft – was bleibt bei dir?</h2><div class="feedback"><strong>Die Fahrt erfüllt die technischen Auftragskriterien.</strong><p>Prüfpunkte, Randfahrt, Endort, Blickrichtung und feste Wiederholung passen in diesem Beispiel.</p></div><p><strong>Du prüfst mit einem Partner oder der Lehrkraft:</strong> Bedeutet deine Grafik dasselbe wie dein Code? Warum gehören genau diese Befehle in einen Durchlauf?</p><table class="trace"><caption>Vorbereitete Vorhersage vor diesem Lauf: Ende (1,3), Blick rechts</caption><thead><tr><th>Beleg</th><th>Spurstelle</th></tr></thead><tbody>${[2,4,7,9,10].map(n=>`<tr><td><label><input type="checkbox" value="${n}" checked>Aktion ${n}</label></td><td>(${s3[n][0]},${s3[n][1]}), ${names[s3[n][2]]}</td></tr>`).join('')}</tbody></table><label for="s3-why">Meine Erklärung zu den ausgewählten Stellen</label><textarea id="s3-why">Beispiel: 2, 4, 7 und 9 erreichen die Prüfpunkte. Aktion 10 dreht am Start nach rechts.</textarea><div class="actions"><button data-action="s3-save" class="primary">Beleg übernehmen · Simulation</button></div><p class="receipt" role="status">${state.s3saved?'Beleg im Beispielstand übernommen. Erklärung noch gemeinsam prüfen.':''}</p></section>`:''}<div class="actions"><button data-screen="rueckkehr">Pause vorbereiten</button><button data-screen="transfer">Übertragen &amp; einordnen →</button></div>`;}
function reentry(){return `<div class="return-layout"><div class="eyebrow">Pause &amp; Rückkehr · vorbereiteter Beispielstand</div><h1>Hier kannst du weiterdenken.</h1><p class="lead">Deine Rückkehrkarte zeigt, woran du gearbeitet hast. Die alte Lösung bleibt zunächst zu.</p><section class="card"><h2>Meine Prüffahrt · S3</h2><dl class="facts"><dt>Mein Stand</dt><dd>Grafik und Code vorhanden. Eine Spur ausgewählt.</dd><dt>Prüfung</dt><dd>Fahrtkriterien geprüft. Erklärung noch besprechen.</dd><dt>Offener Punkt</dt><dd>${esc(state.returnPoint)}</dd><dt>Nächste Handlung</dt><dd>${esc(state.next)}</dd><dt>Speicherung</dt><dd>Nur ein simulierter Rückkehrstand; keine Datei geladen.</dd></dl></section>${!state.retrieval?`<div class="choice"><h2>Kurz unterbrochen?</h2><p>Setze an deiner offenen Frage fort. Eine kurze Pause ist kein späterer Abruf.</p><button data-screen="entwurf" class="primary">Meinen Entwurf öffnen</button></div><div class="choice"><h2>Neuer Termin mit Abruf?</h2><p>Wenn die Lehrkraft einen Abruf eingeplant hat, erinnere dich zuerst ohne die alte Lösung.</p><button data-action="retrieval">Erst erinnern, dann nachsehen</button></div>`:`<section class="card"><h2>Erst erinnern</h2><p>Schreibe einen Körper mit mindestens zwei Grundbefehlen aus dem Gedächtnis. Entfalte zwei Durchläufe. Begründe einen Zustand und markiere eine Unsicherheit.</p><label for="recall">Meine Erinnerung · bleibt flüchtig</label><textarea id="recall" placeholder="Mein Körper … Zwei Durchläufe … Unsicher bin ich bei …"></textarea><div class="actions"><button data-action="recall-compare" class="primary">Mit meiner Erinnerung vergleichen</button><button data-screen="entwurf">Ohne Abruf weiterarbeiten</button></div><p class="micro">Der Abstand zwischen den Terminen wird von der Lehrkraft geklärt. Ein heutiger Test dieses Entwurfs belegt kein späteres Behalten.</p><div id="recall-result" role="status"></div></section>`}<details class="help"><summary>Meine Rückkehrkarte bearbeiten · Simulation</summary><label for="open-point">Was bleibt offen?</label><input id="open-point" value="${esc(state.returnPoint)}"><label for="next-action">Was tue ich als Nächstes?</label><input id="next-action" value="${esc(state.next)}"><button data-action="save-return" class="primary" style="margin-top:14px">Rückkehrkarte im Beispiel merken</button><p id="return-receipt" role="status" class="receipt"></p></details><details class="help"><summary>Kein Arbeitsstand da?</summary><p>Prüfe mit der Lehrkraft das Browserprofil oder eine vorhandene Arbeitsdatei. Eine Datei zuerst ansehen, dann bewusst übernehmen. Ein fehlender Stand sagt nichts darüber aus, was du verstanden hast.</p><p>Wenn nichts wiederherstellbar ist: Erkläre an einem kurzen Beispiel, was ein ganzer Wiederholungskörper ist. Haltet danach die nächste Aufgabe fest.</p><p class="micro">Dateiprüfung und Wiederherstellung sind in diesem Entwurf nicht implementiert.</p></details></div>`;}
function transfer(){return `<div class="eyebrow">Übertragen &amp; einordnen · S4 / S5</div><h1>Gilt die Körperregel auch hier?</h1><p class="lead">Die neue Prüfstation kennt keine Blickrichtung. Hier entscheidet ihr Zustand: frei, belegt oder geprüft.</p><section class="card"><h2>Drei Werkstücke prüfen · S4</h2><p><strong>aufnehmen:</strong> braucht frei → belegt · <strong>prüfen:</strong> braucht belegt → geprüft · <strong>ablegen:</strong> braucht geprüft → frei.</p><div class="split"><div class="code"><strong>A · dreimal ein ganzer Körper</strong><div class="body-frame">aufnehmen → prüfen → ablegen</div></div><div class="code"><strong>B · drei getrennte Körper</strong><p>3 × aufnehmen<br>3 × prüfen<br>3 × ablegen</p></div></div><table class="trace"><caption>Dein Zustandsvergleich · manuell</caption><thead><tr><th>Aktion</th><th>A danach</th><th>B danach</th></tr></thead><tbody><tr><th>Start</th><td>frei</td><td>frei</td></tr>${[1,2,3].map(n=>`<tr><th>${n}</th><td><input aria-label="A Zustand nach Aktion ${n}" placeholder="Zustand"></td><td><input aria-label="B Zustand nach Aktion ${n}" placeholder="Zustand / unmöglich"></td></tr>`).join('')}</tbody></table><label for="station-reason">Welche Gruppierung ist ausführbar? Wo scheitert die andere zuerst, und warum?</label><textarea id="station-reason"></textarea><div class="feedback"><strong>Hier prüfst du selbst.</strong><p>Die Software bewertet diese Begründung nicht. Vergleicht eure Zustandsfolgen und erklärt eine unterschiedliche Stelle.</p></div></section><section class="card"><h2>Was macht das System? · S5</h2><div class="function-cards"><article><h3>A · Zeitsteuerung</h3><p>Sie erhält Zeitpunkte und einen aktuellen Zeitwert, vergleicht sie und löst bei erfüllter Bedingung eine Aktion aus.</p></article><article><h3>B · Wegberechnung</h3><p>Sie erhält Start, Ziel und Verbindungen, verarbeitet diese Daten und gibt einen Weg aus.</p></article><article><h3>C · Papier</h3><p>Eine eindeutige Schrittfolge beschreibt das Sortieren von Karten. Das Blatt führt sie nicht selbst aus.</p></article><article><h3>D · Standbild</h3><p>Du siehst Symbole und Zahlen. Eingaben, Zustandsänderungen und Verarbeitungsregeln sind unbekannt.</p></article></div><label for="system-reason">Nenne für A und B einen notwendigen Ablauf. Was kannst du über C und D sagen – und was nicht?</label><textarea id="system-reason"></textarea><p class="micro">Gemeinsame Sicherung: Eine algorithmische Vorschrift, ihre Ausführung und ein digitales System sind zu unterscheiden.</p></section><button data-screen="rueckkehr">Offenen Punkt festhalten</button>`;}
const views={einstieg:entry,beispiel:example,revision,entwurf:design,rueckkehr:reentry,transfer};
function inputKey(el){return `${state.screen}:${el.id||el.getAttribute('aria-label')||`${el.type}:${el.value}`}`;}
function rememberInputs(){main.querySelectorAll('input,textarea,select').forEach(el=>{draftInputs[inputKey(el)]=el.type==='checkbox'?el.checked:el.value;});}
function render(focus=false){main.innerHTML=views[state.screen]();main.querySelectorAll('input,textarea,select').forEach(el=>{const key=inputKey(el);if(key in draftInputs){if(el.type==='checkbox')el.checked=draftInputs[key];else el.value=draftInputs[key];}});document.querySelectorAll('[data-screen]').forEach(b=>b.toggleAttribute('aria-current',b.dataset.screen===state.screen));document.querySelectorAll('[aria-current]').forEach(b=>b.setAttribute('aria-current','page'));document.querySelector('#storage').textContent=state.mode?`${state.mode} · simuliert`:'Beispielmodus';if(state.screen==='revision'){
 const rows=main.querySelectorAll('.code-row');rows.forEach(el=>el.classList.remove('current'));if(state.run&&state.step>0){const row=state.corrected&&state.step%2===0?rows[1]:rows[0];row?.classList.add('current');}
 if(state.run){const p=document.createElement('p');p.className='micro';p.textContent=runPrediction?`Vor diesem Lauf erfasst: (${runPrediction.x},${runPrediction.y}), Blick ${runPrediction.d}.`:'Dieser Lauf hat keine vorher erfasste Erwartung. Du kannst ihn untersuchen; für einen Beleg brauchst du einen neuen Lauf mit eigener Vorhersage.';main.querySelector('.split .card').append(p);if(!runPrediction){const retry=document.createElement('button');retry.dataset.action='new-run';retry.textContent='Vorhersage für einen neuen Lauf eingeben';main.querySelector('.split .card').append(retry);}}
 for(const [phase,evidence] of Object.entries(revisionEvidence)){if(!evidence)continue;const p=document.createElement('p');p.className='quote';p.textContent=`${phase==='before'?'Vorher':'Nachher'} übernommen: ${evidence.code}. Erwartet (${evidence.prediction.x},${evidence.prediction.y}), ${evidence.prediction.d}. Erste Abweichung: ${evidence.first}. Eigene Begründung: ${evidence.rationale}`;main.querySelector('.savebar').before(p);}
 }if(focus){main.focus();main.scrollIntoView({block:'start'});}}
function go(screen){state.screen=views[screen]?screen:'einstieg';if(location.hash!==`#${state.screen}`)location.hash=state.screen;else render(true);}
document.addEventListener('input',e=>{if(main.contains(e.target)&&e.target.matches('input,textarea,select'))draftInputs[inputKey(e.target)]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(e.target.id==='s0-answer')state.answer=e.target.value;if(e.target.id==='why')state.rationale=e.target.value;});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;rememberInputs();if(b.dataset.screen){go(b.dataset.screen);return;}const action=b.dataset.action;
if(action==='device'||action==='session'){state.mode=action==='device'?'Gerät gewählt':'Nur Sitzung';}
if(action==='s0-next')state.s0=Math.min(3,state.s0+1);if(action==='s0-reset')state.s0=0;
if(action==='s1-next')state.s1=Math.min(8,state.s1+1);if(action==='s1-reset')state.s1=0;
if(action==='run-s2'){const x=Number(draftInputs['revision:s2-x']);const y=Number(draftInputs['revision:s2-y']);const d=draftInputs['revision:s2-d'];runPrediction=Number.isInteger(x)&&x>=1&&x<=4&&Number.isInteger(y)&&y>=1&&y<=4&&names.includes(d)?{x,y,d}:null;state.run=true;state.step=state.corrected?8:3;}
if(action==='new-run'){state.run=false;state.step=0;state.compare=false;runPrediction=null;}
if(action==='group'||action==='ungroup'){state.corrected=action==='group';state.run=false;state.step=0;state.compare=false;state.rationale='';runPrediction=null;for(const k of ['why','first-diff','s2-x','s2-y','s2-d'])delete draftInputs[`revision:${k}`];}
if(action==='prev')state.step=Math.max(0,state.step-1);if(action==='next')state.step=Math.min(state.corrected?8:3,state.step+1);
if(action==='compare')state.compare=true;
if(action==='record'){if(!runPrediction){document.querySelector('#receipt').textContent='Dieser Lauf hat keine vorher erfasste Erwartung. Starte über „Vorhersage für einen neuen Lauf eingeben“ erneut.';return;}if(!state.rationale.trim()||!draftInputs['revision:first-diff']){document.querySelector('#receipt').textContent='Wähle deine erste Abweichung oder „Keine“ und begründe eine passende Spurstelle. Du kannst sie auch mit der Lehrkraft besprechen.';document.querySelector('#why').focus();return;}const phase=state.corrected?'after':'before';revisionEvidence[phase]={code:state.corrected?'wiederhole 4 [vor; links]':'wiederhole 4 [vor]; links',prediction:{...runPrediction},first:draftInputs['revision:first-diff'],rationale:state.rationale};if(state.corrected)state.savedAfter=true;else state.savedBefore=true;}
if(action==='plan')state.s3view='plan';if(action==='code')state.s3view='code';if(action==='s3-run')state.s3run=true;if(action==='s3-prev')state.s3step=Math.max(1,state.s3step-1);if(action==='s3-next')state.s3step=Math.min(10,state.s3step+1);if(action==='s3-save')state.s3saved=true;
if(action==='retrieval')state.retrieval=true;
if(action==='recall-compare'){const val=document.querySelector('#recall').value.trim();document.querySelector('#recall-result').innerHTML=val?'<div class="feedback"><strong>Vergleiche jetzt die Körperregel.</strong><p>Ein Durchlauf umfasst alle Anweisungen im Rahmen. Die Anzahl sagt, wie oft der ganze Körper ausgeführt wird. Zeige das an deiner Erinnerung. Eine offene Stelle klärst du mit der Lehrkraft.</p><button data-screen="entwurf">Jetzt den alten Entwurf ansehen</button></div>':'<div class="feedback warn">Halte zuerst eine Erinnerung oder Unsicherheit fest. Du kannst auch ohne Abruf weiterarbeiten; dann entsteht kein Abrufnachweis.</div>';return;}
if(action==='save-return'){state.returnPoint=document.querySelector('#open-point').value;state.next=document.querySelector('#next-action').value;document.querySelector('#return-receipt').textContent='Im Beispiel gemerkt. Nach dem Neuladen sind diese Eingaben weg.';return;}
if(action){render();const focusTarget=main.querySelector(`[data-action="${action}"]`);if(focusTarget&&!focusTarget.disabled)focusTarget.focus();else main.focus();}
});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus();return;}state.screen=views[location.hash.slice(1)]?location.hash.slice(1):'einstieg';render(true);});
if(matchMedia('(max-width:650px)').matches)document.querySelector('#way-details').open=false;
state.screen=views[location.hash.slice(1)]?location.hash.slice(1):'einstieg';render();
